-- Jalankan di Supabase SQL Editor pada proyek khusus kongres.
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role text not null default 'operator' check(role in ('admin','verifikator','operator','viewer')),active boolean not null default true,created_at timestamptz default now());
create table if not exists public.participants(id uuid primary key default gen_random_uuid(),full_name text not null,organization text not null,position text,phone text,category text not null default 'peserta',rfid_code text unique,status text not null default 'pending' check(status in ('pending','verified','rejected')),sk_path text,accreditation_path text,clarification_path text,payment_path text,mandate_path text,verified_by uuid references public.profiles(id),verified_at timestamptz,created_at timestamptz default now());
create table if not exists public.candidates(id uuid primary key default gen_random_uuid(),full_name text not null,organization text not null,phone text,vision text,status text not null default 'pending' check(status in ('pending','verified','rejected')),sk_path text,accreditation_path text,clarification_path text,payment_path text,verified_by uuid references public.profiles(id),created_at timestamptz default now());
create table if not exists public.sessions(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz default now());
create table if not exists public.attendance(id uuid primary key default gen_random_uuid(),participant_id uuid not null references public.participants(id),session_id uuid not null references public.sessions(id),direction text not null check(direction in ('masuk','keluar')),scanned_by uuid references public.profiles(id),scanned_at timestamptz default now(),created_at timestamptz default now());
create table if not exists public.inventory_items(id uuid primary key default gen_random_uuid(),name text not null,quantity integer not null check(quantity>=0),created_at timestamptz default now());
create table if not exists public.inventory_claims(id uuid primary key default gen_random_uuid(),participant_id uuid not null references public.participants(id),item_id uuid not null references public.inventory_items(id),quantity integer not null check(quantity>0),issued_by uuid references public.profiles(id),created_at timestamptz default now());
create table if not exists public.audit_logs(id bigint generated always as identity primary key,table_name text not null,record_id text,operation text not null,actor uuid,old_row jsonb,new_row jsonb,created_at timestamptz default now());
create or replace function public.my_role() returns text language sql stable security definer set search_path=public as $$select role from public.profiles where id=auth.uid() and active=true$$;
revoke all on function public.my_role() from public;grant execute on function public.my_role() to authenticated;
create or replace function public.audit_changes() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.audit_logs(table_name,record_id,operation,actor,old_row,new_row) values(tg_table_name,coalesce(new.id,old.id)::text,tg_op,auth.uid(),to_jsonb(old),to_jsonb(new));return coalesce(new,old);end$$;
create or replace function public.protect_status() returns trigger language plpgsql set search_path=public as $$begin if (new.status is distinct from old.status or new.verified_by is distinct from old.verified_by) and public.my_role() not in ('admin','verifikator') then raise exception 'Only admin/verifikator may change verification';end if;return new;end$$;
create or replace function public.guard_claim_stock() returns trigger language plpgsql set search_path=public as $$declare available integer;begin perform 1 from public.inventory_items where id=new.item_id for update;select i.quantity-coalesce(sum(c.quantity),0) into available from public.inventory_items i left join public.inventory_claims c on c.item_id=i.id where i.id=new.item_id group by i.quantity;if available is null or available<new.quantity then raise exception 'Stok tidak mencukupi';end if;return new;end$$;
drop trigger if exists stock_guard on public.inventory_claims;create trigger stock_guard before insert on public.inventory_claims for each row execute function public.guard_claim_stock();
create or replace function public.guard_attendance() returns trigger language plpgsql set search_path=public as $$begin if not exists(select 1 from public.participants where id=new.participant_id and status='verified') then raise exception 'Peserta belum terverifikasi';end if;return new;end$$;
drop trigger if exists attendance_guard on public.attendance;create trigger attendance_guard before insert on public.attendance for each row execute function public.guard_attendance();
-- Batasi operator agar tidak mengubah kolom status saat insert.
create or replace function public.protect_insert() returns trigger language plpgsql set search_path=public as $$begin if new.status<>'pending' and public.my_role() not in ('admin','verifikator') then raise exception 'Status awal harus pending';end if;return new;end$$;
do $$declare t text;begin foreach t in array array['participants','candidates'] loop execute format('drop trigger if exists status_guard on public.%I',t);execute format('create trigger status_guard before update on public.%I for each row execute function public.protect_status()',t);execute format('drop trigger if exists insert_guard on public.%I',t);execute format('create trigger insert_guard before insert on public.%I for each row execute function public.protect_insert()',t);end loop;end$$;
do $$declare t text;begin foreach t in array array['profiles','participants','candidates','sessions','attendance','inventory_items','inventory_claims','audit_logs'] loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy profiles_read on public.profiles for select to authenticated using(id=auth.uid() or public.my_role()='admin');
create policy profiles_admin on public.profiles for all to authenticated using(public.my_role()='admin') with check(public.my_role()='admin');
do $$declare t text;begin foreach t in array array['participants','candidates','sessions','attendance','inventory_items','inventory_claims'] loop execute format('create policy %I on public.%I for select to authenticated using(public.my_role() is not null)',t||'_read',t);execute format('create policy %I on public.%I for insert to authenticated with check(public.my_role() in (''admin'',''verifikator'',''operator''))',t||'_insert',t);end loop;end$$;
create policy participants_update on public.participants for update to authenticated using(public.my_role() in ('admin','verifikator')) with check(public.my_role() in ('admin','verifikator'));
create policy candidates_update on public.candidates for update to authenticated using(public.my_role() in ('admin','verifikator')) with check(public.my_role() in ('admin','verifikator'));
create policy audit_read on public.audit_logs for select to authenticated using(public.my_role()='admin');
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('kongres-documents','kongres-documents',false,10485760,array['application/pdf','image/jpeg','image/png']) on conflict(id) do nothing;
create policy documents_upload on storage.objects for insert to authenticated with check(bucket_id='kongres-documents' and public.my_role() in ('admin','verifikator','operator'));
create policy documents_read on storage.objects for select to authenticated using(bucket_id='kongres-documents' and public.my_role() in ('admin','verifikator'));
